window.kbPageData["views/entry/k-96692c77e259dab1"] = {"key":"entry/k-96692c77e259dab1","state":{"route":"entry/k-96692c77e259dab1"},"node":{"id":"k-96692c77e259dab1","mode":"k","title":"反间谍调查中的传唤通知","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["反间谍调查中传唤原因的家属通知义务及例外"],"qs":["国考 2024 地市级 行测#10"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查的，可以暂缓，相关情形消失后应当立即通知。","review":{"definition":"国家安全机关应当及时将传唤原因通知被传唤人家属。无法通知或者通知可能妨碍调查的，可以暂缓，相关情形消失后应当立即通知。","explanation":"甲仍有间谍行为嫌疑这一事实本身不构成暂缓通知的条件。A项把通知时间一律推迟到嫌疑消除后，违反了及时通知及例外情形消失后立即通知的要求，因此是本题应选的错误项。","references":[],"evidence":"除无法通知或者可能妨碍调查的情形以外","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#10":{"paper":"国考 2024 地市级 行测","n":10,"mod":"常识判断","src":["92d0b72e86a6a33d568d.pdf",2],"asrc":["e1792c53900a45f1b9fa.pdf",4],"card":"792ee56bcfdf3ab2c2b8798e","links":[{"id":"k-96692c77e259dab1","role":"直接考查","why":"应及时通知家属，无法通知或可能妨碍调查的情形消失后应立即通知。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-96692c77e259dab1":[["国考 2024 地市级 行测#10"]]}};
